import type { Container } from "postcss";
import type { PostcssResult } from "stylelint";
import type { Syntax } from "../../syntaxes/index.ts";
/**
 * Returns the run between a block's last node and its closing brace as the file spells it: the block's final raw ({@link getBlockAfter}), behind the stray semicolons PostCSS filed with the run in front of them in the last node's `raws.ownSemicolon` where that node closes on a brace of its own.
 * @param syntax - The syntax the rule is built over, which reads the raw.
 * @param statement - The block's statement.
 * @returns The run, or undefined without a raw.
 */
export declare function getBlockTail(syntax: Syntax, statement: Container): string | undefined;
/**
 * Writes the run between a block's last node and its closing brace, parting it back into the two raws {@link getBlockTail} joins: the last node's `raws.ownSemicolon` through as many semicolons as it held, the block's final raw the rest. A write keeps the semicolons in their order, so the ones the last node held are the first ones written.
 * @param syntax - The syntax the rule is built over, which writes the raw.
 * @param statement - The block's statement.
 * @param tail - The run to write.
 */
export declare function setBlockTail(syntax: Syntax, statement: Container, tail: string): void;
/**
 * Asks whether the run in front of the closing brace stands behind a semicolon once `declaration-block-trailing-semicolon` has run, although the parser now reads it as the value of the custom property closing the block: a live `always` writes the semicolon behind a value of whitespace or nothing, with no flag, which keeps its whitespace in front of that semicolon, so the run in front of the brace is the empty `raws.after` behind it.
 * @param syntax - The syntax the rule is built over, which reads the value.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns True where the run is the block's `raws.after` behind that semicolon.
 */
export declare function runStandsBehindTheSemicolon(syntax: Syntax, statement: Container, result: PostcssResult): boolean;
/**
 * Returns the run {@link getBlockTail} returns as `declaration-block-trailing-semicolon` will leave it, so that a reader's answer is one whether that rule has run yet or not: behind a custom property whose value is whitespace or nothing, with no flag, that it writes a semicolon behind, the block's `raws.after` rather than the value.
 * @param syntax - The syntax the rule is built over, which reads the raw.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns The run, or undefined without a raw.
 */
export declare function getBlockTailAsClosed(syntax: Syntax, statement: Container, result: PostcssResult): string | undefined;
/**
 * Writes the run {@link getBlockTailAsClosed} reads where it reads it.
 * @param syntax - The syntax the rule is built over, which writes the raw.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @param tail - The run to write.
 */
export declare function setBlockTailAsClosed(syntax: Syntax, statement: Container, result: PostcssResult, tail: string): void;
/**
 * Finds the stray semicolons of the run {@link getBlockTail} returns that a neighbor takes out in the same run: those of the last node's `raws.ownSemicolon` and those of the block's final raw, each as its own question answers, counted in the joined run.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns The semicolons' indices in the run.
 */
export declare function blockTailTaken(statement: Container, result: PostcssResult): Set<number>;
/**
 * Reads the text a brace rule asks its escape questions over as `declaration-block-trailing-semicolon` will leave it, where the block's last node is a declaration and the text ends with its value, its semicolon and the tail, or with the value holding the tail: a live `never` copy takes the semicolon with the whitespace in front of it, so the first whitespace character of the tail closes a hexadecimal escape ending the value, and a live `always` copy writes the semicolon behind the value, which closes the escape and leaves the tail a run whole. Any other text stands as it is, the tail where it is.
 * @param syntax - The syntax the rule is built over, which reads the value.
 * @param statement - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @param text - The text the rule reads, ending with the tail and the closing brace.
 * @param tail - The run in front of the brace, as {@link getBlockTailAsClosed} reads it.
 * @returns The text as left, and where the tail opens in it.
 */
export declare function blockTextAsClosed(syntax: Syntax, statement: Container, result: PostcssResult, text: string, tail: string): {
    text: string;
    index: number;
};
